use verus::prelude::*;

/// Returns the length of the smallest inner list.  
/// 
/// Requires:
/// - The outer `list` is non‐empty.  
/// 
/// Guarantees:
/// - The result is a lower bound on all inner lengths.
/// - There is at least one inner list whose length equals the result.
#[requires(list.len() > 0)]
#[ensures(
    // result is at most the length of every inner list
    forall |i: usize| i < list.len() ==> result <= list[i].len()
)]
#[ensures(
    // there exists an inner list whose length equals result
    exists |j: usize| j < list.len() && result == list[j].len()
)]
fn smallest_list_length(list: &Vec<Vec<i32>>) -> usize {
    // Since the outer list is guaranteed non-empty, `min` on the lengths iterator
    // will always return `Some`, so `unwrap` is safe.
    list.iter()
        .map(|inner| inner.len())
        .min()
        .unwrap()
}

